// 1. Retrieve webhook input triggers
const triggerData = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json.query || $('Webhook Trigger').first().json || {};

const targetWorkshopDate = (triggerData.workshop_date || '8th October 2026').toLowerCase();
const recordingUrl = triggerData.recording_url || 'https://aifworkshop.prateekmayani.com/portal';
const promptsUrl = triggerData.prompts_url || 'https://aifworkshop.prateekmayani.com/portal';
const testMode = triggerData.test_mode === true || triggerData.test_mode === 'true';
const testEmail = triggerData.test_email || 'prateekmayanii@gmail.com';

const items = $input.all();
const output = [];
const seenEmails = new Set();

let bothCount = 0;
let recOnlyCount = 0;
let proOnlyCount = 0;

for (const item of items) {
  const row = item.json;
  const email = (row.Email || row.email || '').trim().toLowerCase();
  const name = (row.Name || row.name || 'there').trim();
  const wsDate = (row['Workshop Date'] || '').toLowerCase();

  // Date filter: Only process attendees for the targeted workshop date
  if (!wsDate.includes('3 oct') && !wsDate.includes('3rd oct') && !wsDate.includes(targetWorkshopDate)) {
    continue;
  }

  if (!email || !email.includes('@') || seenEmails.has(email)) {
    continue;
  }

  const cleanAmt = parseInt(String(row.Amount).replace(/\D/g, '')) || 0;

  // Strict bump verification (checks explicit column first, then amount)
  const isRec = row['Recording Purchased'] === 'YES' || cleanAmt === 178 || cleanAmt === 377 || cleanAmt === 677 || cleanAmt === 876;
  const isPro = row['Prompts Purchased'] === 'YES' || cleanAmt === 228 || cleanAmt === 377 || cleanAmt === 727 || cleanAmt === 876;

  // If neither bump was purchased, skip completely!
  if (!isRec && !isPro) {
    continue;
  }

  seenEmails.add(email);

  const recipientTarget = testMode ? testEmail : email;

  // Case 1: Both Recording & Prompts Purchased
  if (isRec && isPro) {
    bothCount++;
    output.push({
      json: {
        recipientEmail: recipientTarget,
        recipientName: name,
        bumpType: 'BOTH',
        emailSubject: '🎁 Your Workshop Replay + 300+ Prompts Vault [AI Influencer Masterclass]',
